(function () {
'use strict';
var doc = document;
var config = {};
try {
config = JSON.parse(doc.getElementById('tt-config').textContent) || {};
} catch (error) {
config = {};
}
var enabled = Boolean(config.ga4 || config.pixel);
var cookieName = config.cookie || 'tt_consent';
var loaded = false;
var queue = [];
function readConsent() {
var match = doc.cookie.match(new RegExp('(?:^|; )' + cookieName + '=([^;]*)'));
return match ? decodeURIComponent(match[1]) : null;
}
function writeConsent(value) {
var expires = new Date(Date.now() + (config.days || 180) * 864e5).toUTCString();
doc.cookie = cookieName + '=' + encodeURIComponent(value) + '; expires=' + expires + '; path=/; SameSite=Lax' +
(window.location.protocol === 'https:' ? '; Secure' : '');
}
function injectScript(src) {
var script = doc.createElement('script');
script.async = true;
script.src = src;
doc.head.appendChild(script);
}
function load() {
if (loaded || !enabled) {
return;
}
loaded = true;
if (config.ga4) {
window.dataLayer = window.dataLayer || [];
window.gtag = function () { window.dataLayer.push(arguments); };
window.gtag('js', new Date());
window.gtag('config', config.ga4);
injectScript('https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(config.ga4));
}
if (config.pixel) {
var fbq = window.fbq = function () {
if (fbq.callMethod) {
fbq.callMethod.apply(fbq, arguments);
} else {
fbq.queue.push(arguments);
}
};
if (!window._fbq) {
window._fbq = fbq;
}
fbq.push = fbq;
fbq.loaded = true;
fbq.version = '2.0';
fbq.queue = [];
injectScript('https://connect.facebook.net/en_US/fbevents.js');
fbq('init', config.pixel);
fbq('track', 'PageView');
}
queue.splice(0).forEach(function (item) {
send(item[0], item[1]);
});
}
function send(event, params) {
var consent = readConsent();
if (!enabled || consent === 'denied') {
return;
}
if (consent !== 'granted' || !loaded) {
queue.push([event, params]);
return;
}
if (config.ga4 && window.gtag) {
window.gtag('event', event, params);
}
if (config.pixel && window.fbq) {
var standard = { whatsapp_click: 'Contact', view_item: 'ViewContent' }[event];
var payload = {
content_name: params.product_name,
content_category: params.category,
content_ids: params.product_slug ? [params.product_slug] : undefined,
value: params.price_shown ? Number(params.price_shown) : undefined,
currency: params.price_shown ? 'COP' : undefined
};
if (standard) {
window.fbq('track', standard, payload);
} else {
window.fbq('trackCustom', event, payload);
}
}
}
function paramsOf(element) {
var params = {};
Array.prototype.forEach.call(element.attributes, function (attribute) {
if (attribute.name.indexOf('data-track-') === 0 && attribute.name !== 'data-track-onload') {
params[attribute.name.slice(11).replace(/-/g, '_')] = attribute.value;
}
});
if (!params.page) {
params.page = doc.documentElement.getAttribute('data-page');
}
return params;
}
window.ttTrack = function (event, params) {
var payload = params || {};
if (!payload.page) {
payload.page = doc.documentElement.getAttribute('data-page');
}
send(event, payload);
};
doc.addEventListener('click', function (event) {
var element = event.target.closest('[data-track]');
if (element) {
send(element.getAttribute('data-track'), paramsOf(element));
}
}, true);
Array.prototype.forEach.call(doc.querySelectorAll('[data-track-onload]'), function (element) {
send(element.getAttribute('data-track'), paramsOf(element));
});
if (!enabled) {
return;
}
var banner = doc.querySelector('[data-consent]');
var decision = readConsent();
if (decision === 'granted') {
load();
} else if (decision === null && banner) {
banner.hidden = false;
}
if (banner) {
banner.addEventListener('click', function (event) {
var choice = event.target.closest('[data-consent-choice]');
if (!choice) {
return;
}
var value = choice.getAttribute('data-consent-choice');
var previous = readConsent();
writeConsent(value);
banner.hidden = true;
if (value === 'granted') {
load();
} else {
queue.length = 0;
}
if (value !== 'granted' && previous === 'granted') {
window.location.reload(); // descarga GA4 y Pixel de la página actual
}
});
}
doc.addEventListener('click', function (event) {
if (event.target.closest('[data-consent-open]') && banner) {
banner.hidden = false;
var first = banner.querySelector('button');
if (first) {
first.focus();
}
}
});
})();
